var e={hostControl:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Zarządzaj hostem Linux drukarki - sprawdzaj jego kondycję, steruj usługami działającymi w tle, zwalniaj miejsce na dysku i zmieniaj ustawienia systemowe (czas, ustawienia regionalne, nazwę hosta, sieć, zasilanie).`}},view:{monitor:{t:0,b:{t:2,i:[{t:3}],s:`Monitor`}},services:{t:0,b:{t:2,i:[{t:3}],s:`Usługi`}},cleanup:{t:0,b:{t:2,i:[{t:3}],s:`Czyszczenie`}},system:{t:0,b:{t:2,i:[{t:3}],s:`System`}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Pomoc`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`O sterowaniu hostem`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Zamknij`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Jak czytać`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Czytaj karty temperatury CPU, pamięci, dysku i sieci jednym rzutem oka.`}},{t:0,b:{t:2,i:[{t:3}],s:`Obserwuj tabelę najaktywniejszych procesów, aby zobaczyć, co obciąża CPU w tej chwili.`}},{t:0,b:{t:2,i:[{t:3}],s:`Zostaw automatyczne odświeżanie włączone dla widoku na żywo lub wyłącz je i odświeżaj ręcznie.`}}],topics:{glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Używane tu pojęcia`}}},monitor:{title:{t:0,b:{t:2,i:[{t:3}],s:`Odczyt monitora`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Wszystko tutaj jest tylko do odczytu. Paski stają się bursztynowe powyżej 75% i czerwone powyżej 90%. Temperatura CPU staje się bursztynowa przy 70 °C i czerwona przy 80 °C. Ostrzeżenie o ograniczeniu wydajności pojawia się tylko na płytkach, które je raportują (głównie Raspberry Pi).`}}},services:{title:{t:0,b:{t:2,i:[{t:3}],s:`Zarządzanie usługami`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Każdy wiersz to usługa systemd. Kliknij ją, aby uruchomić/zatrzymać/zrestartować ją, włączyć/wyłączyć przy starcie, zamaskować ją, odczytać jej dziennik lub - w przypadku usług zainstalowanych przez Ciebie - usunąć jej plik jednostki. Zatrzymanie lub wyłączenie usługi wymaga wpisanego lub jednodotykowego potwierdzenia. Usługi krytyczne i chronione są oznaczone; chronionych (jak SSH i ten panel) nie można zatrzymać, aby uniknąć zablokowania sobie dostępu.`}}},cleanup:{title:{t:0,b:{t:2,i:[{t:3}],s:`Zwalnianie miejsca na dysku`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Każdy wiersz jest najpierw skanowany, aby pokazać, ile by zwolnił. Zaznacz te do wyczyszczenia i potwierdź. Oferowane są tylko dane, które można odtworzyć - pamięć podręczna pobierania apt, stary dziennik systemd, ~/.cache, Twoje stare pliki /tmp i zrotowane (nieaktywne) dzienniki. Twój G-code, timelapse i konfiguracje nigdy nie są naruszane.`}}},system:{title:{t:0,b:{t:2,i:[{t:3}],s:`Ustawienia systemowe`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Zmień strefę czasową i zegar hosta, język i klawiaturę, nazwę hosta lub sieć (DHCP / statyczny IP) albo zrestartuj/wyłącz go. Każda zmiana jest stosowana natychmiast. Restart i wyłączenie są odrzucane podczas trwającego wydruku. Zmiana IP może na chwilę przerwać Twoje połączenie z tym panelem.`}}},network:{title:{t:0,b:{t:2,i:[{t:3}],s:`DHCP a statyczny IP`}},body:{t:0,b:{t:2,i:[{t:3}],s:`DHCP (automatycznie) pozwala routerowi przydzielić adres automatycznie. Statyczny (ręcznie) przypina stały adres - ustaw IP, podsieć (CIDR, np. /24), bramę (zwykle Twój router) i DNS. Tylko IPv4. Zmiana adresu połączenia, które obsługuje ten panel, zakończy Twoją sesję; połącz się ponownie pod nowym IP. Błędny statyczny adres lub brama mogą sprawić, że drukarka będzie nieosiągalna, dopóki nie naprawisz tego na samym urządzeniu, dlatego ustawienia są walidowane i wymagają wpisanego potwierdzenia.`}}}},glossary:{host:{term:{t:0,b:{t:2,i:[{t:3}],s:`Host`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Mały komputer Linux (np. Raspberry Pi lub BTT CB1), na którym działają Klipper, Moonraker i FilaMind - oddzielny od mikrokontrolerów drukarki.`}}},load:{term:{t:0,b:{t:2,i:[{t:3}],s:`Średnie obciążenie`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Ile procesów czekało na uruchomienie, uśrednione w ciągu 1 / 5 / 15 minut. W przybliżeniu: wartość bliska liczbie rdzeni oznacza, że CPU jest zajęty; znacznie powyżej oznacza, że jest przeciążony.`}}},swap:{term:{t:0,b:{t:2,i:[{t:3}],s:`Swap`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Miejsce na dysku używane jako bufor, gdy RAM się zapełnia. Intensywne używanie swapu spowalnia hosta - to znak, że brakuje mu pamięci.`}}},throttle:{term:{t:0,b:{t:2,i:[{t:3}],s:`Ograniczanie wydajności`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Gdy płytka zmniejsza prędkość, aby chronić siebie - zwykle z powodu zbyt słabego zasilacza (zbyt niskie napięcie) lub przegrzania. Raportowane głównie na Raspberry Pi.`}}},ntp:{term:{t:0,b:{t:2,i:[{t:3}],s:`NTP / synchronizacja zegara`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Network Time Protocol utrzymuje dokładność zegara hosta. Niezsynchronizowany zegar może zepsuć timelapse, dzienniki i certyfikaty TLS.`}}},locale:{term:{t:0,b:{t:2,i:[{t:3}],s:`Ustawienia regionalne`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Ustawienia języka i układu klawiatury hosta, używane przez system operacyjny do tekstu, dat i mapy klawiszy konsoli.`}}},service:{term:{t:0,b:{t:2,i:[{t:3}],s:`Usługa (jednostka)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Program działający w tle zarządzany przez systemd - Klipper, Moonraker, streamer kamery i stos sieciowy działają jako usługi.`}}},enabled:{term:{t:0,b:{t:2,i:[{t:3}],s:`Włączona / wyłączona`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Czy usługa uruchamia się automatycznie przy starcie. „enabled” uruchamia się przy starcie; „disabled” nie; „static” jest uruchamiana tylko przez inną usługę.`}}},mask:{term:{t:0,b:{t:2,i:[{t:3}],s:`Maskowanie`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Silniejsza forma wyłączenia - usługi nie można uruchomić w ogóle (nawet przez inną usługę), dopóki nie zostanie odmaskowana. Używaj ostrożnie.`}}}}},monitor:{refresh:{t:0,b:{t:2,i:[{t:3}],s:`Odśwież`}},autoRefresh:{t:0,b:{t:2,i:[{t:3}],s:`Automatyczne odświeżanie`}},loading:{t:0,b:{t:2,i:[{t:3}],s:`Odczyt stanu hosta…`}},host:{t:0,b:{t:2,i:[{t:3}],s:`Host`}},hostname:{t:0,b:{t:2,i:[{t:3}],s:`Nazwa hosta`}},distro:{t:0,b:{t:2,i:[{t:3}],s:`System`}},kernel:{t:0,b:{t:2,i:[{t:3}],s:`Jądro`}},uptime:{t:0,b:{t:2,i:[{t:3}],s:`Czas pracy`}},cpu:{t:0,b:{t:2,i:[{t:3}],s:`CPU`}},temp:{t:0,b:{t:2,i:[{t:3}],s:`Temperatura`}},load:{t:0,b:{t:2,i:[{t:3}],s:`Obciążenie (1·5·15m)`}},cores:{t:0,b:{t:2,i:[{t:3}],s:`Rdzenie`}},throttled:{t:0,b:{t:2,i:[{t:3}],s:`Ograniczone`}},memory:{t:0,b:{t:2,i:[{t:3}],s:`Pamięć`}},ram:{t:0,b:{t:2,i:[{t:3}],s:`RAM`}},swap:{t:0,b:{t:2,i:[{t:3}],s:`Swap`}},disk:{t:0,b:{t:2,i:[{t:3}],s:`Dysk`}},network:{t:0,b:{t:2,i:[{t:3}],s:`Sieć`}},iface:{t:0,b:{t:2,i:[{t:3}],s:`Interfejs`}},ip:{t:0,b:{t:2,i:[{t:3}],s:`Adres IP`}},ssid:{t:0,b:{t:2,i:[{t:3}],s:`Wi-Fi`}},signal:{t:0,b:{t:2,i:[{t:3}],s:`Sygnał`}},timeLocale:{t:0,b:{t:2,i:[{t:3}],s:`Czas i ustawienia regionalne`}},timezone:{t:0,b:{t:2,i:[{t:3}],s:`Strefa czasowa`}},ntp:{t:0,b:{t:2,i:[{t:3}],s:`Synchronizacja zegara`}},synced:{t:0,b:{t:2,i:[{t:3}],s:`Zsynchronizowano`}},syncing:{t:0,b:{t:2,i:[{t:3}],s:`Synchronizowanie…`}},ntpOff:{t:0,b:{t:2,i:[{t:3}],s:`Wył.`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Język`}},keymap:{t:0,b:{t:2,i:[{t:3}],s:`Mapa klawiszy`}},topProcesses:{t:0,b:{t:2,i:[{t:3}],s:`Najaktywniejsze procesy`}},command:{t:0,b:{t:2,i:[{t:3}],s:`Polecenie`}},cpuPct:{t:0,b:{t:2,i:[{t:3}],s:`CPU%`}},memPct:{t:0,b:{t:2,i:[{t:3}],s:`MEM%`}},pid:{t:0,b:{t:2,i:[{t:3}],s:`PID`}}},services:{warning:{t:0,b:{t:2,i:[{t:3}],s:`Zatrzymanie lub wyłączenie niewłaściwej usługi może odłączyć drukarkę. Usługi krytyczne są oznaczone; chronionych nie można zatrzymać.`}},search:{t:0,b:{t:2,i:[{t:3}],s:`Szukaj usług…`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Odśwież`}},loading:{t:0,b:{t:2,i:[{t:3}],s:`Tworzenie listy usług…`}},loadingDetail:{t:0,b:{t:2,i:[{t:3}],s:`Odczyt usługi…`}},loadingLogs:{t:0,b:{t:2,i:[{t:3}],s:`Odczyt dziennika…`}},summary:{t:0,b:{t:2,i:[{t:4,k:`total`},{t:3,v:` usług · `},{t:4,k:`active`},{t:3,v:` aktywnych · `},{t:4,k:`failed`},{t:3,v:` z błędem`}]}},filter:{all:{t:0,b:{t:2,i:[{t:3}],s:`Wszystkie`}},active:{t:0,b:{t:2,i:[{t:3}],s:`Aktywne`}},inactive:{t:0,b:{t:2,i:[{t:3}],s:`Nieaktywne`}},failed:{t:0,b:{t:2,i:[{t:3}],s:`Z błędem`}},enabled:{t:0,b:{t:2,i:[{t:3}],s:`Włączone`}}},stateActive:{t:0,b:{t:2,i:[{t:3}],s:`Aktywna`}},stateInactive:{t:0,b:{t:2,i:[{t:3}],s:`Nieaktywna`}},stateFailed:{t:0,b:{t:2,i:[{t:3}],s:`Z błędem`}},critical:{t:0,b:{t:2,i:[{t:3}],s:`Krytyczna`}},protected:{t:0,b:{t:2,i:[{t:3}],s:`Chroniona`}},state:{t:0,b:{t:2,i:[{t:3}],s:`Stan`}},startup:{t:0,b:{t:2,i:[{t:3}],s:`Uruchamianie`}},unitFile:{t:0,b:{t:2,i:[{t:3}],s:`Plik jednostki`}},action:{start:{t:0,b:{t:2,i:[{t:3}],s:`Uruchom`}},stop:{t:0,b:{t:2,i:[{t:3}],s:`Zatrzymaj`}},restart:{t:0,b:{t:2,i:[{t:3}],s:`Zrestartuj`}},enable:{t:0,b:{t:2,i:[{t:3}],s:`Włącz`}},disable:{t:0,b:{t:2,i:[{t:3}],s:`Wyłącz`}},mask:{t:0,b:{t:2,i:[{t:3}],s:`Zamaskuj`}},unmask:{t:0,b:{t:2,i:[{t:3}],s:`Odmaskuj`}}},actionOk:{t:0,b:{t:2,i:[{t:4,k:`action`},{t:3,v:` wykonano.`}]}},actionFailed:{t:0,b:{t:2,i:[{t:4,k:`action`},{t:3,v:` nie powiodło się.`}]}},deleteFailed:{t:0,b:{t:2,i:[{t:3}],s:`Nie udało się usunąć pliku jednostki.`}},confirmAction:{t:0,b:{t:2,i:[{t:4,k:`action`},{t:3,v:` „`},{t:4,k:`name`},{t:3,v:`”?`}]}},confirmYes:{t:0,b:{t:2,i:[{t:3}],s:`Tak, zrób to`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Anuluj`}},deleteUnit:{t:0,b:{t:2,i:[{t:3}],s:`Usuń plik jednostki…`}},deletePrompt:{t:0,b:{t:2,i:[{t:3,v:`To trwale usuwa plik jednostki. Wpisz „`},{t:4,k:`name`},{t:3,v:`”, aby potwierdzić.`}]}},deleteConfirm:{t:0,b:{t:2,i:[{t:3}],s:`Usuń trwale`}},deleted:{t:0,b:{t:2,i:[{t:3}],s:`Plik jednostki usunięto.`}},logs:{t:0,b:{t:2,i:[{t:3}],s:`Ostatni dziennik`}},noLogs:{t:0,b:{t:2,i:[{t:3}],s:`Brak wyjścia dziennika.`}}},cleanup:{subtitle:{t:0,b:{t:2,i:[{t:3}],s:`Zaznacz, co usunąć, a następnie wyczyść. Tylko pamięci podręczne i stare dzienniki - wydruki i konfiguracje pozostają bezpieczne.`}},rescan:{t:0,b:{t:2,i:[{t:3}],s:`Skanuj ponownie`}},scanning:{t:0,b:{t:2,i:[{t:3}],s:`Skanowanie dysku…`}},na:{t:0,b:{t:2,i:[{t:3}],s:`nd.`}},items:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` plików`}]}},freed:{t:0,b:{t:2,i:[{t:3,v:`Zwolniono `},{t:4,k:`size`},{t:3,v:`.`}]}},selectedTotal:{t:0,b:{t:2,i:[{t:3,v:`Wybrano: `},{t:4,k:`size`}]}},clean:{t:0,b:{t:2,i:[{t:3}],s:`Wyczyść zaznaczone`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`Usunąć wybrane elementy?`}},confirmYes:{t:0,b:{t:2,i:[{t:3}],s:`Tak, wyczyść`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Anuluj`}},running:{t:0,b:{t:2,i:[{t:3}],s:`Czyszczenie…`}},someFailed:{t:0,b:{t:2,i:[{t:3}],s:`Niektórych elementów nie udało się wyczyścić.`}},targets:{apt:{label:{t:0,b:{t:2,i:[{t:3}],s:`Pamięć podręczna pakietów`}},desc:{t:0,b:{t:2,i:[{t:3}],s:`Pobrane pliki instalacyjne .deb, których apt już nie potrzebuje.`}}},journal:{label:{t:0,b:{t:2,i:[{t:3}],s:`Dziennik systemowy`}},desc:{t:0,b:{t:2,i:[{t:3}],s:`Stare dzienniki systemd - ograniczone do ostatnich 50 MB.`}}},cache:{label:{t:0,b:{t:2,i:[{t:3}],s:`Pamięć podręczna użytkownika`}},desc:{t:0,b:{t:2,i:[{t:3}],s:`Odtwarzalne pliki w ~/.cache (miniatury, pip itp.).`}}},tmp:{label:{t:0,b:{t:2,i:[{t:3}],s:`Pliki tymczasowe`}},desc:{t:0,b:{t:2,i:[{t:3}],s:`Twoje własne pliki w /tmp starsze niż dzień.`}}},logs:{label:{t:0,b:{t:2,i:[{t:3}],s:`Zrotowane dzienniki`}},desc:{t:0,b:{t:2,i:[{t:3}],s:`Stare, zrotowane dzienniki Klipper/Moonraker (aktywny dziennik jest zachowany).`}}}}},system:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Odczyt ustawień systemowych…`}},done:{t:0,b:{t:2,i:[{t:3}],s:`Gotowe.`}},apply:{t:0,b:{t:2,i:[{t:3}],s:`Zastosuj`}},timeTitle:{t:0,b:{t:2,i:[{t:3}],s:`Czas i data`}},timezone:{t:0,b:{t:2,i:[{t:3}],s:`Strefa czasowa`}},ntp:{t:0,b:{t:2,i:[{t:3}],s:`Ustaw czas automatycznie (NTP)`}},manualTime:{t:0,b:{t:2,i:[{t:3}],s:`Ustaw zegar ręcznie`}},manualTimeHint:{t:0,b:{t:2,i:[{t:3}],s:`Wyłącz automatyczny czas, aby ustawić zegar ręcznie.`}},localeTitle:{t:0,b:{t:2,i:[{t:3}],s:`Język i klawiatura`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Język`}},keymap:{t:0,b:{t:2,i:[{t:3}],s:`Mapa klawiszy konsoli`}},hostnameTitle:{t:0,b:{t:2,i:[{t:3}],s:`Nazwa hosta`}},hostnameHint:{t:0,b:{t:2,i:[{t:3}],s:`Tylko litery, cyfry i myślniki. Pełny efekt po restarcie.`}},powerTitle:{t:0,b:{t:2,i:[{t:3}],s:`Zasilanie`}},powerWarning:{t:0,b:{t:2,i:[{t:3}],s:`Restart i wyłączenie są odrzucane podczas trwającego wydruku.`}},reboot:{t:0,b:{t:2,i:[{t:3}],s:`Zrestartuj`}},shutdown:{t:0,b:{t:2,i:[{t:3}],s:`Wyłącz`}},confirmReboot:{t:0,b:{t:2,i:[{t:3}],s:`Zrestartować host teraz?`}},confirmShutdown:{t:0,b:{t:2,i:[{t:3}],s:`Wyłączyć host teraz?`}},confirmYes:{t:0,b:{t:2,i:[{t:3}],s:`Tak`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Anuluj`}},needsSetup:{t:0,b:{t:2,i:[{t:3}],s:`To działanie wymaga sudo bez hasła. Na drukarce uruchom: sudo bash scripts/install.sh sudoers - następnie spróbuj ponownie.`}},failed:{t:0,b:{t:2,i:[{t:3}],s:`Tej zmiany nie udało się zastosować.`}},network:{title:{t:0,b:{t:2,i:[{t:3}],s:`Sieć (IPv4)`}},unavailable:{t:0,b:{t:2,i:[{t:3}],s:`Edycja sieci nie jest dostępna na tym hoście (NetworkManager nie jest zainstalowany).`}},device:{t:0,b:{t:2,i:[{t:3}],s:`Urządzenie`}},method:{t:0,b:{t:2,i:[{t:3}],s:`Metoda IP`}},auto:{t:0,b:{t:2,i:[{t:3}],s:`DHCP (automatycznie)`}},manual:{t:0,b:{t:2,i:[{t:3}],s:`Statyczny (ręcznie)`}},address:{t:0,b:{t:2,i:[{t:3}],s:`Adres IP`}},cidr:{t:0,b:{t:2,i:[{t:3}],s:`Podsieć (CIDR)`}},gateway:{t:0,b:{t:2,i:[{t:3}],s:`Brama`}},dns:{t:0,b:{t:2,i:[{t:3}],s:`Serwery DNS`}},dnsHint:{t:0,b:{t:2,i:[{t:3}],s:`Rozdzielone przecinkami, np. 1.1.1.1, 8.8.8.8 (opcjonalne)`}},warning:{t:0,b:{t:2,i:[{t:3}],s:`Zmiana IP może przerwać działanie tego panelu - może być konieczne ponowne połączenie pod nowym adresem.`}},apply:{t:0,b:{t:2,i:[{t:3}],s:`Zastosuj ustawienia sieci`}},confirmPrompt:{t:0,b:{t:2,i:[{t:3,v:`To może sprawić, że panel będzie nieosiągalny. Wpisz nazwę urządzenia „`},{t:4,k:`device`},{t:3,v:`”, aby potwierdzić.`}]}},confirmYes:{t:0,b:{t:2,i:[{t:3}],s:`Zastosuj i przełącz`}},applyingReconnect:{t:0,b:{t:2,i:[{t:3}],s:`Stosowanie… jeśli panel przestanie odpowiadać, połącz się ponownie pod nowym IP drukarki.`}}}}}};export{e as default};